            edge = False
            while q:
                rr, cc = q.popleft()
                region.append((rr, cc))
                edge |= rr == 0 or cc == 0 or rr == h - 1 or cc == w - 1
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
