                    if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0
                            and (nr, nc) not in seen):
                        seen.add((nr, nc))
                        q.append((nr, nc))
            if not edge:
                holes.append(region)

    if not holes:
        return out

    # Identify 1-components that border at least one hole.
    ones_seen = set()
    selected = []
