def transform(grid):
    h = len(grid)
    out = [row[:] for row in grid]
    dirs4 = ((1, 0), (-1, 0), (0, 1), (0, -1))
    dirs8 = tuple((dr, dc) for dr in (-1, 0, 1) for dc in (-1, 0, 1)
                  if dr or dc)

    # Zero components not connected to an edge are the cavities.
    seen = set()
    holes = []
    for r in range(h):
        for c in range(len(grid[r])):
            if grid[r][c] != 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            edge = False
            while q:
                rr, cc = q.popleft()
                cells.append((rr, cc))
                if rr in (0, h - 1) or cc in (0, len(grid[rr]) - 1):
                    edge = True
                for dr, dc in dirs4:
                    nr, nc = rr + dr, cc + dc
                    if (0 <= nr < h and 0 <= nc < len(grid[nr])
                            and grid[nr][nc] == 0 and (nr, nc) not in seen):
                        seen.add((nr, nc))
                        q.append((nr, nc))
            if not edge:
                holes.append(cells)
    if not holes:
        return out

    # Select line components adjoining a cavity.
    seen = set()
    selected_components = []
    for r in range(h):
        for c in range(len(grid[r])):
            if grid[r][c] != 1 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                rr, cc = q.popleft()
                comp.append((rr, cc))
                for dr, dc in dirs4:
                    nr, nc = rr + dr, cc + dc
                    if (0 <= nr < h and 0 <= nc < len(grid[nr])
                            and grid[nr][nc] == 1 and (nr, nc) not in seen):
                        seen.add((nr, nc))
                        q.append((nr, nc))
            comp_set = set(comp)
            if any((rr + dr, cc + dc) in comp_set
                   for hole in holes for rr, cc in hole for dr, dc in dirs4):
                selected_components.append(comp)

    selected = {p for comp in selected_components for p in comp}
    hole_cells = {p for hole in holes for p in hole}

    # Inner-facing fringe is 3. The 8-neighborhood captures diagonal near-touches.
    for rr, cc in hole_cells:
        if any((rr + dr, cc + dc) in selected for dr, dc in dirs8):
            out[rr][cc] = 3

